import{_ as n,o as s,c as e,a0 as t}from"./chunks/framework.BpJS36ta.js";const h=JSON.parse('{"title":"Struct","description":"","frontmatter":{},"headers":[],"relativePath":"syntax/struct.md","filePath":"syntax/struct.md"}'),p={name:"syntax/struct.md"};function i(l,a,d,c,o,r){return s(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="struct" tabindex="-1">Struct <a class="header-anchor" href="#struct" aria-label="Permalink to &quot;Struct&quot;">​</a></h1><h2 id="apa-yang-bisa-ditulis" tabindex="-1">Apa yang bisa ditulis? <a class="header-anchor" href="#apa-yang-bisa-ditulis" aria-label="Permalink to &quot;Apa yang bisa ditulis?&quot;">​</a></h2><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>People {</span></span>
<span class="line"><span>    name: string</span></span>
<span class="line"><span>    age: number</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="kapan-digunakan" tabindex="-1">Kapan digunakan? <a class="header-anchor" href="#kapan-digunakan" aria-label="Permalink to &quot;Kapan digunakan?&quot;">​</a></h2><p>Gunakan struct untuk mendefinisikan tipe data dengan field yang telah ditentukan. Struct berfungsi sebagai blueprint untuk membuat object.</p><p>Untuk instance struct yang butuh operasi member (baca/tulis per field, validasi layout saat diisi), gunakan <code>new Object</code> dengan struct sebagai anotasinya — lihat bagian <a href="#instance-struct-new-object">Instance struct</a> di bawah.</p><h2 id="apa-hasilnya" tabindex="-1">Apa hasilnya? <a class="header-anchor" href="#apa-hasilnya" aria-label="Permalink to &quot;Apa hasilnya?&quot;">​</a></h2><p>Struct dibuat dengan nama diikuti block <code>{ }</code> yang berisi field declarations. Setiap field memiliki nama dan type annotation.</p><h3 id="validasi-type-analyzer" tabindex="-1">Validasi type (analyzer) <a class="header-anchor" href="#validasi-type-analyzer" aria-label="Permalink to &quot;Validasi type (analyzer)&quot;">​</a></h3><p>Deklarasi struct berlaku sebagai kontrak type. Assignment / annotation yang memakai nama struct divalidasi terhadap layout-nya:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Point {</span></span>
<span class="line"><span>  x: number</span></span>
<span class="line"><span>  y: number</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>p: Point = { x: 10, y: 20 }   # OK</span></span>
<span class="line"><span>q: Point = { x: 10, y: &quot;a&quot; }  # TypeError: expected &#39;number&#39;, got &#39;string&#39;</span></span>
<span class="line"><span>r: Nope = {}                  # TypeError: type &#39;Nope&#39; tidak dikenal</span></span></code></pre></div><p>Validasi bersifat rekursif (struct dalam struct, array of struct), dan field struct dengan type yang tidak dikenal ditolak saat deklarasi. Tidak ada forward reference antar struct — deklarasikan dulu sebelum dipakai.</p><h3 id="instance-struct-new-object" tabindex="-1">Instance struct (new Object) <a class="header-anchor" href="#instance-struct-new-object" aria-label="Permalink to &quot;Instance struct (new Object)&quot;">​</a></h3><p><code>new Object(_, { ... })</code> membuat instance struct: field diisi langsung dari object literal, tipe setiap field divalidasi terhadap layout, dan instance membawa method member <code>has/get/set/update/delete</code>:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>People {</span></span>
<span class="line"><span>    name: string</span></span>
<span class="line"><span>    age: number</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>data: People = new Object(_, { name: &quot;rudi&quot;, age: 20 })</span></span>
<span class="line"><span>print(data.name)</span></span>
<span class="line"><span>print(data.age)</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rudi</span></span>
<span class="line"><span>20</span></span></code></pre></div><p>Instance boleh kosong dulu, field diisi belakangan lewat <code>set</code> — argumen pertama boleh nama field (tanpa tanda kutip) atau object literal untuk merge:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p: People = new Object()</span></span>
<span class="line"><span>p.set(name, &quot;anggi&quot;)     # nama field langsung — tanpa kutip</span></span>
<span class="line"><span>p.set(age, 25)</span></span>
<span class="line"><span>p.set({ age: 26 })       # merge dari object literal</span></span>
<span class="line"><span>print(p.name)</span></span>
<span class="line"><span>print(p.age)</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>anggi</span></span>
<span class="line"><span>26</span></span></code></pre></div><p>Akses member biasa dan validasi layout tetap berlaku:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data.age = 21            # OK — tipe cocok</span></span>
<span class="line"><span>data.city = &quot;x&quot;          # TypeError: unknown field</span></span></code></pre></div><p>Method member yang tersedia pada instance:</p><table tabindex="0"><thead><tr><th>Method</th><th>Bentuk</th><th>Hasil</th></tr></thead><tbody><tr><td><code>has(k)</code></td><td>string / nama field</td><td>true bila field ada</td></tr><tr><td><code>get(k)</code></td><td>string / nama field</td><td>nilai field</td></tr><tr><td><code>set(k, v)</code> / <code>set({...})</code></td><td>nama field atau object literal</td><td>tulis satu field / merge — divalidasi layout</td></tr><tr><td><code>update({...})</code></td><td>object literal</td><td>merge — divalidasi layout</td></tr><tr><td><code>delete(k)</code></td><td>string / nama field</td><td>hapus field</td></tr></tbody></table><h3 id="ref-—-binding-dua-arah" tabindex="-1">Ref — binding dua arah <a class="header-anchor" href="#ref-—-binding-dua-arah" aria-label="Permalink to &quot;Ref — binding dua arah&quot;">​</a></h3><p><code>new Object(ref, init)</code> menghubungkan instance ke object lain: penulisan lewat <code>set</code>/<code>update</code> terlihat di ref, dan member assign menembus untuk field yang sudah ada di ref:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a = new Object()</span></span>
<span class="line"><span>a.name = &quot;awal&quot;</span></span>
<span class="line"><span>b = new Object(a, {})    # b terhubung ke a</span></span>
<span class="line"><span>b.set(name, &quot;ubah&quot;)</span></span>
<span class="line"><span>print(a.name)            # ubah — terlihat di ref</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ubah</span></span></code></pre></div><p>Tanpa argumen apa pun, <code>new Object()</code> membuat instance dinamis penuh (tanpa kontrak struct) dengan method member yang sama.</p><h3 id="contoh-execution" tabindex="-1">Contoh execution <a class="header-anchor" href="#contoh-execution" aria-label="Permalink to &quot;Contoh execution&quot;">​</a></h3><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>People {</span></span>
<span class="line"><span>    name: string</span></span>
<span class="line"><span>    age: number</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>person = { name: &quot;Rupa&quot;, age: 20 }</span></span>
<span class="line"><span>print(person.name)</span></span>
<span class="line"><span>print(person.age)</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rupa</span></span>
<span class="line"><span>20</span></span></code></pre></div><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Point {</span></span>
<span class="line"><span>    x: number</span></span>
<span class="line"><span>    y: number</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>p = { x: 10, y: 20 }</span></span>
<span class="line"><span>print(p.x)</span></span>
<span class="line"><span>print(p.y)</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10</span></span>
<span class="line"><span>20</span></span></code></pre></div>`,38)])])}const b=n(p,[["render",i]]);export{h as __pageData,b as default};
